for insert to authenticated with check (bucket_id='site-content' and private.is_admin(array['super_admin']::public.user_role[]));
create policy "Super admins update website media" on storage.objects
for update to authenticated using (bucket_id='site-content' and private.is_admin(array['super_admin']::public.user_role[]))
with check (bucket_id='site-content' and private.is_admin(array['super_admin']::public.user_role[]));
create policy "Super admins delete website media" on storage.objects
for delete to authenticated using (bucket_id='site-content' and private.is_admin(array['super_admin']::public.user_role[]));

