create table public.support_tickets (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  ticket_number text not null unique default ('IHL-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8))),
  product text not null check (product in ('corporate','datasub','schoolpro','consult','host','engineering','account')),
  subject text not null,
  category text not null default 'general',
  priority text not null default 'normal' check (priority in ('low','normal','high','urgent')),
  message text not null,
  status text not null default 'open' check (status in ('open','assigned','in_progress','waiting_customer','resolved','closed')),
  assigned_to uuid references auth.users(id) on delete set null,
  resolution text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  resolved_at timestamptz
);

create table public.support_ticket_messages (
  id uuid primary key default gen_random_uuid(),
  ticket_id uuid not null references public.support_tickets(id) on delete cascade,
  sender_id uuid not null references auth.users(id) on delete restrict,
  message text not null,
  is_internal boolean not null default false,
  created_at timestamptz not null default now()
);

create index support_tickets_user_created_idx on public.support_tickets(user_id, created_at desc);
create index support_tickets_product_status_idx on public.support_tickets(product, status, created_at desc);
