alter table public.support_tickets enable row level security;
alter table public.support_ticket_messages enable row level security;

create policy "Customers create support tickets" on public.support_tickets
for insert to authenticated
with check (user_id = (select auth.uid()));

create policy "Customers and scoped admins view support tickets" on public.support_tickets
for select to authenticated
using (
  user_id = (select auth.uid())
  or private.has_product_access(product, 'view')
  or private.has_product_access('corporate', 'view')
);

create policy "Scoped admins update support tickets" on public.support_tickets
for update to authenticated
using (
  private.has_product_access(product, 'edit')
  or private.has_product_access('corporate', 'edit')
)
with check (
  private.has_product_access(product, 'edit')
  or private.has_product_access('corporate', 'edit')
);

create policy "Ticket participants view support messages" on public.support_ticket_messages
for select to authenticated
using (
  exists (
    select 1 from public.support_tickets t
    where t.id = ticket_id
      and (
        t.user_id = (select auth.uid())
        or private.has_product_access(t.product, 'view')
        or private.has_product_access('corporate', 'view')
      )
      and (not is_internal or private.has_product_access(t.product, 'view') or private.has_product_access('corporate', 'view'))
  )
);

create policy "Ticket participants create support messages" on public.support_ticket_messages
for insert to authenticated
with check (
  sender_id = (select auth.uid())
  and exists (
    select 1 from public.support_tickets t
    where t.id = ticket_id
      and (
        (t.user_id = (select auth.uid()) and not is_internal)
        or private.has_product_access(t.product, 'edit')
        or private.has_product_access('corporate', 'edit')
      )
  )
);

