grant select, insert, update, delete on table public.password_login_security to supabase_auth_admin;

create or replace function public.hook_password_login_security(event jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := (event->>'user_id')::uuid;
  v_valid boolean := coalesce((event->>'valid')::boolean, false);
  v_failed integer := 0;
  v_locked_until timestamptz;
begin
  select failed_attempts, locked_until
    into v_failed, v_locked_until
  from public.password_login_security
  where user_id = v_user_id;

  if v_locked_until is not null and v_locked_until > now() then
    return jsonb_build_object(
      'decision', 'reject',
      'message', 'Account temporarily locked after repeated failed sign-in attempts. Try again after 10 minutes or use Forgot password.',
      'should_logout_user', false
    );
  end if;

  if v_valid then
    insert into public.password_login_security(user_id, failed_attempts, last_failed_at, locked_until, updated_at)
    values (v_user_id, 0, null, null, now())
    on conflict (user_id) do update
      set failed_attempts = 0, last_failed_at = null, locked_until = null, updated_at = now();
    return jsonb_build_object('decision', 'continue');
  end if;

  v_failed := case
    when v_locked_until is not null and v_locked_until <= now() then 1
    else coalesce(v_failed, 0) + 1
  end;

  v_locked_until := case when v_failed >= 5 then now() + interval '10 minutes' else null end;

  insert into public.password_login_security(user_id, failed_attempts, last_failed_at, locked_until, updated_at)
  values (v_user_id, v_failed, now(), v_locked_until, now())
  on conflict (user_id) do update
    set failed_attempts = excluded.failed_attempts,
        last_failed_at = excluded.last_failed_at,
        locked_until = excluded.locked_until,
        updated_at = excluded.updated_at;

  if v_failed >= 5 then
    return jsonb_build_object(
      'decision', 'reject',
      'message', 'Too many incorrect password attempts. This account is locked for 10 minutes. Use Forgot password if needed.',
      'should_logout_user', false
    );
  end if;

  return jsonb_build_object('decision', 'continue');
end;
$$;

revoke execute on function public.hook_password_login_security(jsonb) from public, anon, authenticated;
grant execute on function public.hook_password_login_security(jsonb) to supabase_auth_admin;

comment on function public.hook_password_login_security(jsonb) is
'Password Verification Hook: locks password authentication for 10 minutes after 5 consecutive invalid attempts; successful verification resets the counter.';

