create table if not exists public.host_dns_zones(id uuid primary key default gen_random_uuid(),service_id uuid not null references host_services(id) on delete cascade,domain_name text not null,status text not null default 'active',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
