create table if not exists public.host_payments(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles(id),invoice_id uuid references host_invoices(id) on delete set null,amount numeric not null check(amount>0),currency text not null default 'NGN',provider_reference text,status text not null default 'pending',paid_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.host_notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles(id) on delete cascade,service_id uuid references host_services(id) on delete cascade,title text not null,body text not null,kind text not null default 'general',read_at timestamptz,created_at timestamptz not null default now());
