do $$ declare t text; begin foreach t in array array['host_dns_zones','host_dns_records','host_ssl_certificates','host_backups','host_mailboxes','host_migrations','host_invoices','host_payments','host_notifications','host_usage_snapshots'] loop execute format('alter table public.%I enable row level security',t); execute format('grant select,insert,update,delete on public.%I to authenticated',t); end loop; end $$;
